// @generated by:gauntlet run:anatoly-extensible-fingerprints
mod common;

use anatoly::{scan::scan_configured, scan_options::ScanOptions};
use common::{Server, limits, response};
use serde_json::{Value, json};
use std::process::Command;

fn observe(status: &str, headers: &str, body: &str, route: &str) -> Value {
    let (status, headers, body) = (status.to_owned(), headers.to_owned(), body.to_owned());
    let server = Server::new(move |_| response(&status, &headers, &body));
    let mut settings = ScanOptions {
        samples: 1,
        discover: false,
        ..ScanOptions::default()
    };
    settings.network.no_proxy = true;
    serde_json::to_value(
        scan_configured(&format!("{}{route}", server.url), limits(), &settings).unwrap(),
    )
    .unwrap()
}

fn laravel(report: &Value) -> &Value {
    report["technologies"]
        .as_array()
        .unwrap()
        .iter()
        .find(|t| t["name"] == "Laravel")
        .unwrap_or_else(|| panic!("missing Laravel: {report}"))
}

fn assert_unknown_php_version(report: &Value) {
    assert!(report["version"].is_null());
    assert!(report["version_candidates"].as_array().unwrap().is_empty());
    assert_eq!(report["verdict"], "inconclusive");
}

#[test]
fn l01_explicit_laravel_headers_expose_the_framework_version_independently_of_php() {
    for header in [
        "X-Laravel-Version: 12.3.4\r\n",
        "X-Powered-By: Laravel/v12.3.4\r\n",
        "X-Powered-By: Laravel/12.3.4\r\n",
    ] {
        let report = observe("200 OK", header, "application", "");

        assert_eq!(laravel(&report)["versions"], json!(["12.3.4"]));
        assert_eq!(laravel(&report)["runtime_hint"], "PHP");
        assert_eq!(report["runtime"]["status"], "inferred");
        assert_unknown_php_version(&report);
    }
}

#[test]
fn l02_composer_locked_laravel_version_does_not_establish_the_installed_php_version() {
    let report = observe(
        "200 OK",
        "Content-Type: application/json\r\n",
        r#"{
        "packages":[{"name":"laravel/framework","version":"v12.3.4"}],
        "platform":{"php":"8.3.12"}}
    "#,
        "composer.lock",
    );

    assert_eq!(laravel(&report)["versions"], json!(["12.3.4"]));
    assert!(
        laravel(&report)["observations"]
            .as_array()
            .unwrap()
            .iter()
            .any(|o| o["version"] == "12.3.4")
    );
    assert_unknown_php_version(&report);
}

#[test]
fn l03_laravel_error_panel_versions_remain_framework_evidence_without_exact_php_proof() {
    let report = observe(
        "500 Internal Server Error",
        "",
        r#"<!doctype html><html><body>
        <h1>RuntimeException</h1><div>PHP 8.3.12</div><div>Laravel 12.3.4</div>
        <p>An exception occurred while rendering the application.</p></body></html>"#,
        "",
    );

    assert_eq!(laravel(&report)["versions"], json!(["12.3.4"]));
    assert!(
        laravel(&report)["observations"]
            .as_array()
            .unwrap()
            .iter()
            .any(|o| o["http_status"] == 500)
    );
    assert_unknown_php_version(&report);
}

#[test]
fn l03_documentary_and_inert_laravel_error_examples_do_not_identify_the_application() {
    for (status, body) in [
        (
            "200 OK",
            "<article>Laravel 12.3.4 uses PHP 8.3.12.</article>",
        ),
        (
            "500 Internal Server Error",
            "<article><h1>RuntimeException</h1><p>PHP 8.3.12 Laravel 12.3.4</p></article>",
        ),
        (
            "500 Internal Server Error",
            "<!-- <h1>RuntimeException</h1><div>PHP 8.3.12 Laravel 12.3.4</div> -->",
        ),
        (
            "500 Internal Server Error",
            "<script>const sample = 'RuntimeException PHP 8.3.12 Laravel 12.3.4';</script>",
        ),
        (
            "500 Internal Server Error",
            "<pre>RuntimeException PHP 8.3.12 Laravel 12.3.4</pre>",
        ),
    ] {
        let report = observe(status, "", body, "");

        assert!(
            !report["technologies"]
                .as_array()
                .unwrap()
                .iter()
                .any(|t| t["name"] == "Laravel"),
            "{body}: {report}"
        );
        assert_unknown_php_version(&report);
    }
}

#[test]
fn l04_mixed_frameworks_infer_php_only_from_the_php_application_marker() {
    let report = observe(
        "200 OK",
        "X-Powered-By: Express/5.1.0\r\nX-Laravel-Version: 12.3.4\r\n",
        "application",
        "",
    );

    let entries = report["technologies"].as_array().unwrap();
    let express = entries.iter().find(|t| t["name"] == "Express").unwrap();
    assert_ne!(express["runtime_hint"], "PHP");
    assert_eq!(laravel(&report)["runtime_hint"], "PHP");
    assert_eq!(report["runtime"]["status"], "inferred");
    assert_unknown_php_version(&report);
}

#[test]
fn l04_explicit_php_version_proof_remains_separate_from_a_different_laravel_version() {
    let report = observe(
        "200 OK",
        "X-Powered-By: PHP/8.4.26\r\nX-Laravel-Version: 12.3.4\r\n",
        "application",
        "",
    );

    assert_eq!(laravel(&report)["versions"], json!(["12.3.4"]));
    assert_eq!(report["runtime"]["status"], "declared");
    assert_eq!(report["version_status"], "affected_range");
    assert_eq!(report["verdict"], "potentially_affected");
    assert_eq!(report["version_candidates"].as_array().unwrap().len(), 1);
}

#[test]
fn l04_laravel_versions_are_visible_in_terminal_output_while_php_remains_unknown() {
    let server =
        Server::new(|_| response("200 OK", "X-Laravel-Version: 12.3.4\r\n", "application"));

    let output = Command::new(env!("CARGO_BIN_EXE_anatoly"))
        .args([
            "scan",
            &server.url,
            "--profile",
            "quick",
            "--delay-ms",
            "0",
            "--no-proxy",
            "--no-banner",
            "--color",
            "never",
        ])
        .output()
        .unwrap();

    assert_eq!(output.status.code(), Some(2));
    let terminal = String::from_utf8(output.stdout).unwrap();
    assert!(
        terminal.contains("Laravel") && terminal.contains("12.3.4"),
        "{terminal}"
    );
    assert!(
        terminal.to_ascii_lowercase().contains("inferred"),
        "{terminal}"
    );
    assert_eq!(server.paths.lock().unwrap().len(), 1);
}
